import { spawn } from 'node:child_process';
import { mkdtempSync, writeFileSync, readFileSync, mkdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import net from 'node:net';

const SERVER = '/root/bench-runs/h4-671cf6e0/server.mjs';
const dir = mkdtempSync(path.join(tmpdir(), 'bk-'));

function run(env, cwd = dir) {
  const child = spawn(process.execPath, [SERVER], { cwd, env: { ...process.env, ...env } });
  let out = '', err = '';
  child.stdout.on('data', (d) => (out += d));
  child.stderr.on('data', (d) => (err += d));
  const exited = new Promise((r) => child.on('exit', (code) => r({ code, out, err })));
  const ready = new Promise((r) => {
    child.stdout.on('data', () => { const m = out.match(/:(\d+)\n$/); if (m) r(Number(m[1])); });
    exited.then(() => r(null));
  });
  return { child, exited, ready, get out() { return out; } };
}

async function req(port, method, p, body, headers = {}) {
  const res = await fetch(`http://127.0.0.1:${port}${p}`, { method, body, headers });
  const text = await res.text();
  return `${res.status} ${res.headers.get('content-type')} ${text}`;
}

function raw(port, data) {
  return new Promise((resolve) => {
    const s = net.connect(port, '127.0.0.1', () => s.end(data));
    let buf = '';
    s.on('data', (d) => (buf += d));
    s.on('close', () => resolve(buf.split('\r\n')[0] + ' | ' + buf.split('\r\n\r\n')[1]));
  });
}

